INSERT INTO `notifications` VALUES (1,75,'❌ Hồ sơ không được duyệt','Hồ sơ xin học bổng \"Học bổng Tiếp sức Đến trường 2025\" của bạn không được duyệt. Lý do: không đủ chuẩn','ERROR',0,'2025-12-21 09:48:01'),(2,84,'🎉 Chúc mừng! Hồ sơ được duyệt','Hồ sơ xin học bổng \"Trợ cấp Xã hội theo Nghị định 81 năm học 2025-2026\" của bạn đã được duyệt. Vui lòng kiểm tra thông tin tài khoản ngân hàng để nhận tiền.','SUCCESS',0,'2025-12-21 10:14:40');
