INSERT INTO `scholarships` VALUES (76,32,NULL,'Học bổng Vingroup - Đào tạo Thạc sĩ, Tiến sĩ 2025','HK2','2025-2026',100000000,10,'Học bổng toàn phần từ Tập đoàn Vingroup dành cho sinh viên xuất sắc theo học Thạc sĩ, Tiến sĩ tại các trường đại học hàng đầu trong và ngoài nước. Bao gồm: học phí, sinh hoạt phí, bảo hiểm y tế. Cam kết làm việc tại Vingroup sau tốt nghiệp.','{\"min_drr\": 85, \"min_gpa\": 3.5, \"require_poor\": false}','2025-03-01 00:00:00','2025-05-31 00:00:00','FINISHED','2025-12-13 23:09:33',NULL,'2025-12-13 23:33:10'),(77,33,NULL,'Học bổng Samsung Talent 2025','HK1','2025-2026',25000000,20,'Học bổng từ Samsung Việt Nam dành cho sinh viên ngành Điện tử, CNTT, Cơ khí tại các trường kỹ thuật hàng đầu. Mỗi suất 20-30 triệu đồng. Sinh viên được nhận có cơ hội thực tập và làm việc tại Samsung.','{\"min_drr\": 80, \"min_gpa\": 3.2, \"require_poor\": false}','2025-12-01 00:00:00','2026-02-28 00:00:00','OPEN','2025-12-13 23:09:33',NULL,'2025-12-13 23:25:19'),(78,33,NULL,'Học bổng Honda Y-E-S 2025','HK1','2025-2026',20000000,15,'Học bổng Honda Y-E-S (Young Engineer and Scientist\'s Award) từ Honda Việt Nam, trao hàng năm từ 2006. Dành cho sinh viên ngành Kỹ thuật, Khoa học có thành tích xuất sắc. Mỗi suất 20 triệu đồng và cơ hội tham quan nhà máy Honda.','{\"min_drr\": 75, \"min_gpa\": 3, \"require_poor\": false}','2025-12-01 00:00:00','2026-02-28 00:00:00','OPEN','2025-12-13 23:09:33',NULL,'2025-12-13 23:25:19'),(79,1,NULL,'Học bổng Phát triển Nguồn nhân lực ĐBSCL 2025','HK1','2025-2026',12000000,100,'Học bổng từ Chương trình Phát triển Nguồn nhân lực vùng ĐBSCL. Dành cho sinh viên các tỉnh ĐBSCL theo học các ngành trọng điểm: Nông nghiệp, Thủy sản, Môi trường, Y tế, Giáo dục. Cam kết về địa phương công tác sau tốt nghiệp.','{\"min_drr\": 70, \"min_gpa\": 2.5, \"require_poor\": true}','2025-12-01 00:00:00','2026-02-28 00:00:00','OPEN','2025-12-13 23:09:33',NULL,'2025-12-13 23:25:19'),(80,32,NULL,'Học bổng Chương trình Tài năng HCMUT 2025','HK1','2025-2026',30000000,50,'Học bổng toàn phần dành cho sinh viên Chương trình Tài năng và Chương trình Tiên tiến tại ĐH Bách Khoa TP.HCM. Bao gồm: Miễn 100% học phí, hỗ trợ sinh hoạt phí, ưu tiên ký túc xá, cơ hội trao đổi sinh viên quốc tế.','{\"min_drr\": 85, \"min_gpa\": 3.5, \"require_poor\": false}','2025-12-01 00:00:00','2026-02-28 00:00:00','OPEN','2025-12-13 23:09:33',NULL,'2025-12-13 23:25:19'),(81,33,NULL,'Học bổng Thủ khoa Đầu vào HUST 2025','HK1','2025-2026',50000000,20,'Học bổng toàn phần 4 năm dành cho thủ khoa, á khoa kỳ thi tuyển sinh đại học và sinh viên đạt giải Olympic quốc gia, quốc tế. Bao gồm: Miễn 100% học phí toàn khóa, hỗ trợ sinh hoạt phí 5 triệu/tháng, laptop, ký túc xá miễn phí.','{\"min_drr\": 90, \"min_gpa\": 3.8, \"require_poor\": false}','2025-12-01 00:00:00','2026-02-28 00:00:00','OPEN','2025-12-13 23:09:33',NULL,'2025-12-13 23:33:10'),(82,34,NULL,'Học bổng Khuyến nông 2025','HK1','2025-2026',8000000,60,'Học bổng từ Quỹ Khuyến nông Việt Nam và các doanh nghiệp nông nghiệp dành cho sinh viên ngành Nông học, Chăn nuôi, Thú y, Lâm nghiệp. Ưu tiên con em nông dân, sinh viên vùng nông thôn.','{\"min_drr\": 70, \"min_gpa\": 2.8, \"require_poor\": false}','2025-12-01 00:00:00','2026-02-28 00:00:00','OPEN','2025-12-13 23:09:33',NULL,'2025-12-13 23:25:19'),(83,1,NULL,'Học bổng Vallet 2025','HK1','2025-2026',30000000,30,'Học bổng từ Quỹ Vallet (Pháp) do Giáo sư Odon Vallet sáng lập năm 1999. Dành cho sinh viên nghèo vượt khó học giỏi. Mỗi suất trị giá khoảng 1.000-1.500 USD (25-35 triệu VNĐ). Đây là một trong những học bổng uy tín nhất Việt Nam, đã trao hơn 50.000 suất trong 25 năm qua.','{\"min_drr\": 75, \"min_gpa\": 3, \"require_poor\": true}','2025-12-01 00:00:00','2026-02-28 00:00:00','OPEN','2025-12-13 23:09:33',NULL,'2025-12-13 23:33:10'),(84,32,NULL,'Học bổng Vallet 2025','HK1','2025-2026',30000000,30,'Học bổng từ Quỹ Vallet (Pháp) do Giáo sư Odon Vallet sáng lập năm 1999. Dành cho sinh viên nghèo vượt khó học giỏi. Mỗi suất trị giá khoảng 1.000-1.500